/**
 * Minimal in-memory storage adapter, implementing the Storage adapter shape.
 * This adapter is NOT durable; it only demonstrates the persist-before-advance contract.
 *
 * You can replace it with your own adapter that writes:
 * - HardState (term, vote, commit)
 * - Entries (log entries)
 * - Snapshot (optional)
 *
 * Adapter shape expected by RaftNode:
 * {
 *   async initialState(id) -> optional: load initial hard state, conf state, snapshot, entries
 *   async persistReady(id, ready) -> must persist hard state, entries, snapshot before resolve
 * }
 */
export class InMemoryStorage {
  constructor() {
    // Track last persisted states by node id (for inspection in examples/tests)
    this.hardState = new Map(); // id -> { term, vote, commit }
    this.entries = new Map();   // id -> array of entries
    this.snapshots = new Map(); // id -> snapshot
  }

  /**
   * Optionally load an initial state. For in-memory, there is nothing to load.
   * A real adapter would read from disk and return:
   *  { hardState?, confState?, snapshot?, entries? }
   */
  async initialState(id) {
    return {};
  }

  /**
   * Persist the Ready set before raft.advance():
   * - ready.hardState?
   * - ready.entries?
   * - ready.snapshot?
   * This method must fsync (durably persist) in real adapters before resolving.
   */
  async persistReady(id, ready) {
    if (ready.hardState) {
      this.hardState.set(id, ready.hardState);
    }
    if (Array.isArray(ready.entries) && ready.entries.length) {
      const existing = this.entries.get(id) || [];
      this.entries.set(id, existing.concat(ready.entries));
    }
    if (ready.snapshot && ready.snapshot.metadata) {
      this.snapshots.set(id, ready.snapshot);
    }
    // No-op delay; real implementation should ensure durability before resolve
    return;
  }
}
